namespace sv_cac966dcf9524e28895707ba10cfeded.Services;

public record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 30),
            new(2, "Margherita Pizza", "Simple pizza with San Marzano tomatoes, mozzarella, and fresh basil.", 45),
            new(3, "Risotto alla Milanese", "Creamy saffron-infused risotto from Milan.", 40),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Marinated chicken in a creamy spiced tomato sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach curry with cubes of paneer cheese.", 35),
            new(6, "Biryani", "Fragrant layered rice dish with spices and tender meat.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Spit-grilled pork tacos with pineapple, cilantro, and onion.", 40),
            new(8, "Mole Poblano", "Rich chocolate and chili sauce served over chicken.", 90),
            new(9, "Elote", "Grilled street corn with mayo, cotija cheese, and chili powder.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate slow API call
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_cac966dcf9524e28895707ba10cfeded.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@Sort">Italian</a> |
    <a href="/recipes/2?sort=@Sort">Indian</a> |
    <a href="/recipes/3?sort=@Sort">Mexican</a>
</nav>

<div style="margin-top: 0.5rem;">
    <label>
        Sort:
        <select @bind="Sort" @bind:after="OnSortChanged">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert" style="margin-top: 1rem;">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div style="margin-top: 1rem;">
        <p><em>Loading recipes…</em></p>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div style="margin-top: 0.5rem;">
            <small><em>Refreshing…</em></small>
        </div>
    }

    <ul style="margin-top: 1rem;">
        @foreach (var recipe in GetSortedRecipes())
        {
            <li>
                <strong>@recipe.Title</strong> — @recipe.Description
                <br /><small>Prep time: @recipe.PrepTimeMinutes min</small>
            </li>
        }
    </ul>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when cuisine changes, not when sort changes
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;

        // Show "Refreshing…" if we already have data; otherwise show loading placeholder
        if (_recipes is not null)
        {
            _isRefreshing = true;
        }

        var cuisineToLoad = CuisineId;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineToLoad, token);

            // Only apply results if we haven't been cancelled
            token.ThrowIfCancellationRequested();

            _recipes = results;
            _loadedCuisineId = cuisineToLoad;
            _error = null;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was superseded — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineToLoad);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineToLoad);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private void OnSortChanged()
    {
        // Update URL without triggering a full navigation/reload
        var uri = Navigation.GetUriWithQueryParameter("sort", Sort);
        Navigation.NavigateTo(uri);
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return Enumerable.Empty<Recipe>();

        return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes.OrderByDescending(r => r.PrepTimeMinutes)
            : _recipes.OrderByDescending(r => r.Id);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

